#!/usr/bin/env python3
"""Generate docs/*.md and the README topic index from data/*.yaml.

Usage: python scripts/build.py [--check]
  --check  exit non-zero if generated files are out of date (for CI)
"""
from __future__ import annotations

import re
import sys

from common import DOCS, NEW_ID, ROOT, iter_papers, load_topics, paper_link, paper_year

TOPIC_LABEL = {
    "surveys": "Surveys", "end-to-end": "End-to-end", "perception-mapping": "Perception", "prediction-planning": "Planning",
    "llm-vlm": "LLM/VLM", "vla": "VLA", "reasoning-rl": "Reasoning/RL", "world-models": "World models", "simulation": "Simulation",
    "datasets": "Datasets", "benchmarks": "Benchmarks", "safety-robustness": "Safety", "cooperative-v2x": "V2X", "industry": "Industry",
}
START, END = "<!-- TOPICS:START -->", "<!-- TOPICS:END -->"


def esc(text: str) -> str:
    return str(text).replace("|", "\\|")


def venue_text(p) -> str:
    """'CVPR'25' -> 'CVPR 2025'; arXiv-only entries get no venue (the site shows 'preprint')."""
    v = p.get("venue", "")
    if not v or v.lower() == "arxiv":
        return ""
    v = re.sub(r"'(\d\d)\b", lambda m: " 20" + m.group(1), v)
    if p.get("year") and not re.search(r"\d{4}", v):
        v += f" {p['year']}"
    return v


def entry_line(p, extra: str = "") -> str:
    """Same entry format the website parser expects: **Title**: note: [Link](url) - [Code](url) · *Venue Year*"""
    base = " - ".join(y for y in (p.get("org"), p.get("note")) if y)
    note = f"{base} {extra}".strip() if extra else base
    line = f"- **{p['title']}**" + (f": {note}" if note else "") + f": [Link]({paper_link(p)})"
    if p.get("code"):
        line += f" - [Code]({p['code']})"
    venue = venue_text(p)
    return line + (f" · *{venue}*" if venue else "")


def render_topic(topic) -> str:
    out = [f"# {topic['title']}", "", "<!-- generated from data/%s.yaml; do not edit by hand -->" % topic["slug"], ""]
    if topic.get("intro"):
        out += [topic["intro"].strip(), ""]
    n = sum(1 for _ in iter_papers(topic))
    out += [f"**{n} entries**, newest first within each section. Add papers by editing `data/{topic['slug']}.yaml` (see [CONTRIBUTING](../CONTRIBUTING.md)).", ""]
    for section in topic.get("sections", []):
        out += [f"## {section['name']}", ""]
        if section.get("desc"):
            out += [section["desc"].strip(), ""]
        papers = sorted(section["papers"], key=lambda p: (-(paper_year(p) or 0), -(int(str(p.get("id", "0")).replace(".", "")) if p.get("id") else 0), p["title"].lower()))
        out += [entry_line(p) for p in papers]
        out.append("")
    return "\n".join(out)


def render_index(topics) -> str:
    lines = ["| Topic | Entries | What is inside |", "|---|---|---|"]
    for t in topics:
        n = sum(1 for _ in iter_papers(t))
        lines.append(f"| [{t['title']}](docs/{t['slug']}.md) | {n} | {esc(t.get('summary', ''))} |")
    total = sum(sum(1 for _ in iter_papers(t)) for t in topics)
    lines += ["", f"**Total: {total} entries across {len(topics)} topics.**"]
    return "\n".join(lines)


def render_recent(topics) -> str:
    """One page with every 2025+ arXiv paper, newest first, grouped by quarter."""
    intro = (ROOT / "scripts" / "recent_intro.md").read_text(encoding="utf-8").strip()
    seen, rows = {}, []
    for t in topics:
        for _, p in iter_papers(t):
            pid = str(p.get("id", ""))
            if not NEW_ID.match(pid) or int(pid[:2]) < 25:
                continue
            if pid in seen:
                seen[pid]["topics"].append(t)
                continue
            seen[pid] = {"paper": p, "topics": [t]}
            rows.append(pid)
    rows.sort(reverse=True)
    out = ["# Recent Papers (2025-2026)", "", "<!-- generated by scripts/build.py; do not edit by hand -->", "", intro, "",
           f"**{len(rows)} papers**, newest first (by arXiv id). A paper in several topics is listed once.", ""]
    current = None
    for pid in rows:
        p, tps = seen[pid]["paper"], seen[pid]["topics"]
        quarter = f"20{pid[:2]} Q{(int(pid[2:4]) - 1) // 3 + 1}"
        if quarter != current:
            current = quarter
            out += ["", f"## {quarter}", ""]
        topics_txt = "(" + ", ".join(TOPIC_LABEL.get(t["slug"], t["title"]) for t in tps) + ")"
        out.append(entry_line(p, topics_txt))
    out.append("")
    return "\n".join(out)


def main() -> int:
    check = "--check" in sys.argv
    topics = load_topics()
    stale = []
    DOCS.mkdir(exist_ok=True)
    for t in topics:
        path = DOCS / f"{t['slug']}.md"
        text = render_topic(t) + "\n"
        if check:
            if not path.exists() or path.read_text(encoding="utf-8") != text:
                stale.append(str(path))
        else:
            path.write_text(text, encoding="utf-8")
    recent_path = DOCS / "recent.md"
    recent = render_recent(topics)
    if check:
        if not recent_path.exists() or recent_path.read_text(encoding="utf-8") != recent:
            stale.append(str(recent_path))
    else:
        recent_path.write_text(recent, encoding="utf-8")
    readme = ROOT / "README.md"
    body = readme.read_text(encoding="utf-8")
    if START in body and END in body:
        head, rest = body.split(START, 1)
        _, tail = rest.split(END, 1)
        new = f"{head}{START}\n{render_index(topics)}\n{END}{tail}"
        if check:
            if new != body:
                stale.append("README.md")
        else:
            readme.write_text(new, encoding="utf-8")
    if check and stale:
        print("Out of date (run `python scripts/build.py`):", *stale, sep="\n  ")
        return 1
    print("ok" if check else f"built {len(topics)} topics")
    return 0


if __name__ == "__main__":
    sys.exit(main())
